    if '治具' in raw or 'fixture' in raw.lower():
        patterns['fixture'] += 1
    if '静态电流' in raw or 'idle current' in raw.lower():
        patterns['current_high'] += 1
    if '烧录' in raw or 'flash' in raw.lower() or 'program' in raw.lower():
        patterns['flash'] += 1
    if '校验' in raw or 'CRC' in raw or 'checksum' in raw.lower():
        patterns['checksum'] += 1
    if '启动' in raw or 'boot' in raw.lower() or 'OS fail' in raw:
        patterns['boot'] += 1
    if 'ESD' in raw or '静电' in raw:
        patterns['esd'] += 1
    if '探针磨损' in raw or 'probe worn' in raw.lower():
        patterns['probe_worn'] += 1
    if '压伤' in raw or 'pressure mark' in raw.lower():
        patterns['pressure_mark'] += 1
    if '版本不符' in raw or 'version' in raw.lower():
        patterns['version'] += 1
    if '反向' in raw or 'reversed' in raw.lower() or 'polarity' in raw.lower():
        patterns['reversed'] += 1
    if '少件' in raw or 'missing' in raw.lower():
        patterns['missing'] += 1
    if '漏电' in raw or 'hipot' in raw.lower() or 'leakage' in raw.lower():
        patterns['leakage'] += 1
    if '校准' in raw or 'cal data' in raw.lower():
        patterns['cal_data'] += 1
    if '污染' in raw or '残留' in raw or 'contamination' in raw.lower():
        patterns['contamination'] += 1
    if '插拔' in raw or 'connector wear' in raw.lower() or 'SMA' in raw:
        patterns['connector_wear'] += 1
    if '异常' in raw and '确认' in raw:
        patterns['generic_abnormal'] += 1

print('Pattern frequencies:')
for p, c in sorted(patterns.items(), key=lambda x: -x[1]):
    print(f'  {p}: {c}')
